window.__finlexDocLoaded(10001,{"id":10001,"articles":[{"id":1000001,"no":"Enforcement Focus","heading":"2026 IFRS & Sustainability Priorities (ESMA32-2064178921-9738)","text":"[IFRS Financial Statements]\n• Geopolitical risks and uncertainties: issuers must transparently reflect macro/geopolitical volatility in impairment assumptions (IAS 36), going concern assessments (IAS 1/IAS 8), and significant judgement disclosures.\n• Restructuring provisions (IAS 37.70–83): verify that a detailed formal plan and valid expectation exist at the reporting date before recognising a provision.\n• Debt restructuring (IFRS 9.3.3.2 & B3.3.6): rigorously apply the 10% present-value test and qualitative assessment to determine substantial modification vs. extinguishment.\n\n[Sustainability & Connected Reporting]\n• Ensure consistency between financial statement assumptions and sustainability disclosures (impacts, risks, opportunities, policies, actions, targets, and metrics).\n\nOfficial ESMA release: https://www.esma.europa.eu/press-news/esma-news/esma-sets-out-2026-european-common-enforcement-priorities","seq":0}]});
